mapper.insert:
INSERT INTO monographs (
slug, title, subtitle, newspaper_source_id, edition_date, edition_date_to,
editorial_note, colophon, central_question, method_note, cover_image_url,
citation_format_template, status, view_count, is_active, created_by
) VALUES (
#{slug}, #{title}, #{subtitle}, #{newspaperSourceId}, #{editionDate}, #{editionDateTo},
#{editorialNote}, #{colophon}, #{centralQuestion}, #{methodNote}, #{coverImageUrl},
#{citationFormatTemplate}, #{status}, #{viewCount}, #{isActive}, #{createdBy}
)

mapper.select:
SELECT m.id, m.slug, m.title, m.subtitle, m.edition_date as editionDate, m.cover_image_url as coverImageUrl, m.status, m.view_count as viewCount, m.published_at as publishedAt, ns.name as newspaperSourceName, ns.slug as newspaperSourceSlug, COALESCE(ec.total_articles, 0) as totalArticles, COALESCE(ec.in_book_count, 0) as inBookCount, COALESCE(ec.appendix_count, 0) as appendixCount, COALESCE(ec.word_count, 0) as wordCount, CEIL(COALESCE(ec.word_count, 0) / 200.0)::int as readingTimeMinutes FROM monographs m JOIN newspaper_sources ns ON ns.id = m.newspaper_source_id
WHERE m.is_active = true
AND m.status = 'published'
AND m.status = #{criteria.status}
AND (m.title ILIKE CONCAT('%', #{criteria.searchQuery}, '%') OR m.subtitle ILIKE CONCAT('%', #{criteria.searchQuery}, '%') OR ns.name ILIKE CONCAT('%', #{criteria.searchQuery}, '%'))
AND ns.slug = #{criteria.sourceSlug}
AND EXTRACT(YEAR FROM m.edition_date) BETWEEN #{criteria.decade} AND (#{criteria.decade} + 9)
ORDER BY
m.title m.view_count m.edition_date
ASC DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM monographs m JOIN newspaper_sources ns ON ns.id = m.newspaper_source_id WHERE m.is_active = true
AND m.status = 'published'
AND m.status = #{criteria.status}
AND (m.title ILIKE CONCAT('%', #{criteria.searchQuery}, '%') OR m.subtitle ILIKE CONCAT('%', #{criteria.searchQuery}, '%') OR ns.name ILIKE CONCAT('%', #{criteria.searchQuery}, '%'))
AND ns.slug = #{criteria.sourceSlug}
AND EXTRACT(YEAR FROM m.edition_date) BETWEEN #{criteria.decade} AND (#{criteria.decade} + 9)

mapper.insert:
INSERT INTO monograph_entries (
monograph_id, chapter_id, article_id, role, text_status,
entry_order, position_label, column_info, editorial_note
) VALUES (
#{monographId}, #{chapterId}, #{articleId}, #{role}, #{textStatus},
#{entryOrder}, #{positionLabel}, #{columnInfo}, #{editorialNote}
)

mapper.select:
SELECT term, definition FROM monograph_glossary
WHERE monograph_id = #{monographId}
ORDER BY term_order, term

SELECT COUNT(*) FROM monograph_chapters mc
WHERE mc.monograph_id = #{monographId}
AND NOT EXISTS (SELECT 1 FROM monograph_entries me WHERE me.chapter_id = mc.id)
